import{_ as s,o as e,c as a,a2 as n}from"./chunks/framework.C-vCXMwJ.js";const k=JSON.parse('{"title":"Troubleshooting & FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md","lastUpdated":null}'),t={name:"guide/troubleshooting.md"};function o(l,i,h,r,d,p){return e(),a("div",null,[...i[0]||(i[0]=[n('<h1 id="troubleshooting-faq" tabindex="-1">Troubleshooting &amp; FAQ <a class="header-anchor" href="#troubleshooting-faq" aria-label="Permalink to &quot;Troubleshooting &amp; FAQ&quot;">​</a></h1><p>Solutions to the most common build, runtime, and migration issues.</p><h2 id="events-are-not-reaching-my-child-components" tabindex="-1">Events Are Not Reaching My Child Components <a class="header-anchor" href="#events-are-not-reaching-my-child-components" aria-label="Permalink to &quot;Events Are Not Reaching My Child Components&quot;">​</a></h2><p><strong>Symptom:</strong> Buttons, inputs, or menus render on screen, but keyboard or mouse input does nothing.</p><p><strong>Cause:</strong> You used <code class="shiki-inline"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"><a href="/FTXUI/en/v6.1.7/api/component#renderer" class="code-ref">Renderer</a></span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> child-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"><a href="/FTXUI/en/v6.1.7/api/dom#render-1" class="code-ref">Render</a></span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(); })</span></code> without passing <code>child</code> (or a <code>Container</code> holding your children) as the first argument.</p><p><strong>Fix:</strong> Always pair a <code>Container</code> with <code class="shiki-inline"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"><a href="/FTXUI/en/v6.1.7/api/component#renderer" class="code-ref">Renderer</a></span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(container, ...)</span></code>:</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">auto</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> container </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Container</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"><a href="/FTXUI/en/v6.1.7/api/component#vertical" class="code-ref">Vertical</a></span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({input, button});</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">auto</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ui </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> <a href="/FTXUI/en/v6.1.7/api/component#renderer" class="code-ref">Renderer</a></span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(container, [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] {</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  return</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> <a href="/FTXUI/en/v6.1.7/api/dom#vbox" class="code-ref">vbox</a></span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({input-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"><a href="/FTXUI/en/v6.1.7/api/dom#render-1" class="code-ref">Render</a></span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(), button-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"><a href="/FTXUI/en/v6.1.7/api/dom#render-1" class="code-ref">Render</a></span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()})</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">         |</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> <a href="/FTXUI/en/v6.1.7/api/dom#border" class="code-ref">border</a>;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>See the <a href="/FTXUI/en/v6.1.7/guide/mental-model">Mental Model</a> guide for details.</p><hr><h2 id="undefined-references-when-linking-manually" tabindex="-1">Undefined References When Linking Manually <a class="header-anchor" href="#undefined-references-when-linking-manually" aria-label="Permalink to &quot;Undefined References When Linking Manually&quot;">​</a></h2><p><strong>Symptom:</strong> Linker errors mentioning <a href="/FTXUI/en/v6.1.7/api/class/node"><code class="shiki-inline"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ftxui</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::Node</span></code></a>, <a href="/FTXUI/en/v6.1.7/api/class/screen"><code class="shiki-inline"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ftxui</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::Screen</span></code></a>, or <a href="/FTXUI/en/v6.1.7/api/component#element"><code class="shiki-inline"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ftxui</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::Element</span></code></a>.</p><p><strong>Fix:</strong> With static libraries, link order matters (<code>component</code> depends on <code>dom</code>, which depends on <code>screen</code>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">g++</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.cpp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lftxui-component</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lftxui-dom</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lftxui-screen</span></span></code></pre></div><p>With CMake, simply link <code class="shiki-inline"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ftxui</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::ftxui</span></code> (or <code class="shiki-inline"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ftxui</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::component</span></code>, which pulls in <code>dom</code> and <code>screen</code> transitively).</p><hr><h2 id="mingw-cross-compilation-on-linux-mutex-is-not-a-member-of-std" tabindex="-1">MinGW Cross-Compilation on Linux (<code>&#39;mutex&#39; is not a member of &#39;std&#39;</code>) <a class="header-anchor" href="#mingw-cross-compilation-on-linux-mutex-is-not-a-member-of-std" aria-label="Permalink to &quot;MinGW Cross-Compilation on Linux (`&#39;mutex&#39; is not a member of &#39;std&#39;`)&quot;">​</a></h2><p><strong>Symptom:</strong> Building with <code>x86_64-w64-mingw32-g++</code> on Debian/Ubuntu fails with <code>error: &#39;mutex&#39; is not a member of &#39;std&#39;</code>.</p><p><strong>Fix:</strong> The default MinGW compiler on Debian/Ubuntu uses the <code>win32</code> threading model, which does not implement C++11 <code>&lt;mutex&gt;</code>/<code>&lt;thread&gt;</code>. Switch to the <code>posix</code> variant:</p><ul><li>In your CMake toolchain file, set <code>CMAKE_CXX_COMPILER</code> to <code>x86_64-w64-mingw32-g++-posix</code>, or</li><li>Run <code>sudo update-alternatives --config x86_64-w64-mingw32-g++</code> and select <code>x86_64-w64-mingw32-g++-posix</code>.</li></ul><hr><h2 id="windows-macro-collisions-rgb-drawtext-min-max" tabindex="-1">Windows Macro Collisions (<code class="shiki-inline"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"><a href="/FTXUI/en/v6.1.7/api/screen#rgb" class="code-ref">RGB</a></span></code>, <code class="shiki-inline"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"><a href="/FTXUI/en/v6.1.7/api/class/canvas#drawtext" class="code-ref">DrawText</a></span></code>, <code>min</code>, <code>max</code>) <a class="header-anchor" href="#windows-macro-collisions-rgb-drawtext-min-max" aria-label="Permalink to &quot;Windows Macro Collisions (`RGB`, `DrawText`, `min`, `max`)&quot;">​</a></h2><p><strong>Symptom:</strong> Strange compile errors in <code>&lt;ftxui/screen/color.hpp&gt;</code> or <code>&lt;ftxui/dom/canvas.hpp&gt;</code> after including <code>&lt;windows.h&gt;</code>.</p><p><strong>Fix:</strong> Define <code>NOMINMAX</code> and <code>WIN32_LEAN_AND_MEAN</code> before including <code>&lt;windows.h&gt;</code> (or pass <code>-DNOMINMAX</code> in CMake). FTXUI undefines <code class="shiki-inline"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"><a href="/FTXUI/en/v6.1.7/api/screen#rgb" class="code-ref">RGB</a></span></code> and <code class="shiki-inline"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"><a href="/FTXUI/en/v6.1.7/api/class/canvas#drawtext" class="code-ref">DrawText</a></span></code> in its headers, but defining <code>NOMINMAX</code> prevents <code class="shiki-inline"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::min</span></code>/<code class="shiki-inline"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::max</span></code> conflicts.</p><hr><h2 id="colors-unicode-or-mouse-not-working-in-a-terminal" tabindex="-1">Colors, Unicode, or Mouse Not Working in a Terminal <a class="header-anchor" href="#colors-unicode-or-mouse-not-working-in-a-terminal" aria-label="Permalink to &quot;Colors, Unicode, or Mouse Not Working in a Terminal&quot;">​</a></h2><ul><li><strong>Override color detection:</strong><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Terminal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"><a href="/FTXUI/en/v6.1.7/api/screen#setcolorsupport" class="code-ref">SetColorSupport</a></span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Terminal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"><a href="/FTXUI/en/v6.1.7/api/class/color" class="code-ref">Color</a></span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::TrueColor);</span></span></code></pre></div></li><li><strong>Disable Unicode block characters / use ASCII fallbacks:</strong><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">auto</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> quirks </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Terminal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GetQuirks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">quirks.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetComponentAscii</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Terminal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetQuirks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(quirks);</span></span></code></pre></div></li><li><strong>Windows 7 / legacy consoles:</strong> Legacy Windows <code>conhost</code> (before Windows 10) does not support Virtual Terminal escape sequences (<code>ENABLE_VIRTUAL_TERMINAL_PROCESSING</code>). Use Windows Terminal or a modern VT100-compatible terminal.</li></ul><hr><h2 id="migrating-from-ftxui-v6-to-v7" tabindex="-1">Migrating from FTXUI v6 to v7 <a class="header-anchor" href="#migrating-from-ftxui-v6-to-v7" aria-label="Permalink to &quot;Migrating from FTXUI v6 to v7&quot;">​</a></h2><p>FTXUI v7 renamed three core classes for clarity (deprecated aliases remain available for backwards compatibility):</p><table tabindex="0"><thead><tr><th>FTXUI v6 (deprecated)</th><th>FTXUI v7</th><th>Header</th></tr></thead><tbody><tr><td><code class="shiki-inline"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"><a href="/FTXUI/en/v6.1.7/api/class/screeninteractive" class="code-ref">ScreenInteractive</a></span></code></td><td><code>App</code></td><td><code>&lt;ftxui/component/app.hpp&gt;</code></td></tr><tr><td><code class="shiki-inline"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"><a href="/FTXUI/en/v6.1.7/api/class/pixel" class="code-ref">Pixel</a></span></code> / <code class="shiki-inline"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"><a href="/FTXUI/en/v6.1.7/api/class/image#pixelat" class="code-ref">PixelAt</a></span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></code></td><td><code>Cell</code> / <code class="shiki-inline"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">CellAt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></code></td><td><code>&lt;ftxui/screen/cell.hpp&gt;</code></td></tr><tr><td><code class="shiki-inline"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"><a href="/FTXUI/en/v6.1.7/api/class/image" class="code-ref">Image</a></span></code> / <code class="shiki-inline"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"><a href="/FTXUI/en/v6.1.7/api/class/canvas#drawimage" class="code-ref">DrawImage</a></span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></code></td><td><code>Surface</code> / <code class="shiki-inline"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">DrawSurface</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></code></td><td><code>&lt;ftxui/screen/surface.hpp&gt;</code></td></tr></tbody></table>',30)])])}const g=s(t,[["render",o]]);export{k as __pageData,g as default};
